"""
Batch adaptive denoising with zero-phase candidate selection and
persistence-controlled reversal suppression.

The output is aligned to input indices window_size - 1 onward.
"""
import numpy as np

try:
    from scipy.signal import savgol_filter, butter, sosfiltfilt
    _HAVE_SCIPY = True
except Exception:
    savgol_filter = None
    butter = None
    sosfiltfilt = None
    _HAVE_SCIPY = False


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1 or x.size < window_size:
        raise ValueError("Input signal length must be >= window_size")
    return np.convolve(x, np.ones(window_size) / float(window_size), "valid")


def _finite_signal(x):
    z = np.asarray(x, dtype=float).copy()
    good = np.isfinite(z)
    if not np.any(good):
        return np.zeros_like(z)
    if not np.all(good):
        q = np.arange(z.size)
        z[~good] = np.interp(q[~good], q[good], z[good])
    return z


def _sigma(v):
    v = np.asarray(v, dtype=float)
    if v.size == 0:
        return np.finfo(float).eps
    med = np.median(v)
    return max(1.4826 * np.median(np.abs(v - med)), np.finfo(float).eps)


def _median3(x):
    if x.size < 3:
        return x.copy()
    p = np.pad(x, (1, 1), mode="edge")
    return np.median(np.stack((p[:-2], p[1:-1], p[2:])), axis=0)


def _odd_span(requested, n):
    hi = n if n % 2 else n - 1
    return max(3, min(hi, int(requested) | 1))


def _smooth(x, span):
    n = x.size
    if n < 5:
        return x.copy()
    span = _odd_span(span, n)
    if span < 5:
        return x.copy()
    degree = min(3, span - 2)
    if _HAVE_SCIPY:
        return np.asarray(savgol_filter(x, span, degree, mode="mirror"), dtype=float)

    # Centered local cubic fallback.
    h = span // 2
    u = np.arange(-h, h + 1, dtype=float)
    a = np.column_stack((np.ones(span), u, u * u, u * u * u))
    w = np.linalg.pinv(a)[0]
    p = np.pad(x, (h, h), mode="reflect")
    return np.convolve(p, w[::-1], mode="valid")


def _turns(y):
    d = np.diff(y)
    if d.size < 2:
        return np.empty(0, dtype=int)
    s = np.sign(d)
    for i in range(1, s.size):
        if s[i] == 0:
            s[i] = s[i - 1]
    for i in range(s.size - 2, -1, -1):
        if s[i] == 0:
            s[i] = s[i + 1]
    return np.flatnonzero(s[:-1] * s[1:] < 0) + 1


def _persistence_project(y, scale, window_size):
    """Iteratively remove the least prominent local extremum pair."""
    y = np.asarray(y, dtype=float).copy()
    n = y.size
    if n < 5:
        return y
    threshold = max(0.55 * scale, _sigma(np.diff(y)) * 0.16)
    max_passes = max(2, n // 2)

    for _ in range(max_passes):
        t = _turns(y)
        if t.size == 0:
            break
        knots = np.r_[0, t, n - 1]
        best = None
        best_value = np.inf
        for j in range(1, knots.size - 1):
            a, k, b = int(knots[j - 1]), int(knots[j]), int(knots[j + 1])
            width = b - a
            if width < 2:
                continue
            base = y[a] + (y[b] - y[a]) * (k - a) / float(width)
            prominence = abs(y[k] - base)
            local_tau = threshold * (1.0 + 0.08 * np.sqrt(width))
            if prominence < local_tau and prominence < best_value:
                best_value = prominence
                best = (a, b)
        if best is None:
            break
        a, b = best
        y[a:b + 1] = np.linspace(y[a], y[b], b - a + 1)

    return y


def _ar_modal_candidates(z, local):
    """Fit stable ridge AR models in both directions and reconstruct damped modes."""
    z = np.asarray(z, dtype=float)
    local = np.asarray(local, dtype=float)
    n = z.size
    if n < 32 or not np.all(np.isfinite(z)):
        return []

    scale = max(_sigma(np.diff(z)), np.finfo(float).eps)
    level = float(np.median(z))
    target = z - level
    candidates = []

    for order in (4, 6, 8, 12):
        if n <= 2 * order + 8:
            continue

        forward_x = np.asarray(
            [target[i - order:i][::-1] for i in range(order, n)],
            dtype=float
        )
        forward_y = target[order:]
        reverse_target = target[::-1]
        reverse_x = np.asarray(
            [reverse_target[i - order:i][::-1]
             for i in range(order, n)],
            dtype=float
        )
        reverse_y = reverse_target[order:]

        design = np.vstack((forward_x, reverse_x))
        response = np.concatenate((forward_y, reverse_y))
        gram = design.T @ design
        ridge = 0.02 * max(float(np.trace(gram)) / order, 1.0)

        try:
            ar = np.linalg.solve(
                gram + ridge * np.eye(order, dtype=float),
                design.T @ response
            )
            roots = np.roots(np.r_[1.0, -ar])
        except (np.linalg.LinAlgError, ValueError):
            continue

        if roots.size == 0 or not np.all(np.isfinite(roots)):
            continue

        roots = roots[
            (np.abs(roots) >= 0.82) &
            (np.abs(roots) <= 1.02)
        ]
        if roots.size == 0:
            continue

        t = np.linspace(-1.0, 1.0, n)
        basis = [np.ones(n, dtype=float), t]
        used = []

        for root in roots:
            if root.imag < -1e-8:
                continue
            radius = float(np.abs(root))
            phase = float(np.angle(root))

            if abs(root.imag) < 1e-7:
                mode = np.power(radius, t * (n - 1) * 0.5)
                mode /= max(np.linalg.norm(mode), np.finfo(float).eps)
                basis.append(mode)
                continue

            if any(abs(root - prior) < 1e-4 for prior in used):
                continue
            used.append(root)

            envelope = np.power(
                radius, t * (n - 1) * 0.5
            )
            cosine = envelope * np.cos(phase * np.arange(n))
            sine = envelope * np.sin(phase * np.arange(n))
            cosine /= max(np.linalg.norm(cosine), np.finfo(float).eps)
            sine /= max(np.linalg.norm(sine), np.finfo(float).eps)
            basis.extend((cosine, sine))

        if len(basis) <= 2:
            continue

        design_modes = np.column_stack(basis)
        if not np.all(np.isfinite(design_modes)):
            continue

        mode_gram = design_modes.T @ design_modes
        mode_ridge = 0.01 * max(
            float(np.trace(mode_gram)) / design_modes.shape[1], 1.0
        )
        weights = np.ones(n, dtype=float)
        coefficients = None

        for _ in range(3):
            weighted = design_modes * weights[:, None]
            weighted_target = z * weights
            try:
                coefficients = np.linalg.solve(
                    weighted.T @ weighted +
                    mode_ridge * np.eye(design_modes.shape[1]),
                    weighted.T @ weighted_target
                )
            except np.linalg.LinAlgError:
                coefficients = None
                break

            residual = z - design_modes @ coefficients
            cutoff = max(1.5 * _sigma(residual), 0.25 * scale)
            weights = np.minimum(
                1.0,
                cutoff / np.maximum(np.abs(residual), cutoff)
            )

        if coefficients is None:
            continue

        reconstruction = np.asarray(
            design_modes @ coefficients, dtype=float
        )
        if not np.all(np.isfinite(reconstruction)):
            continue

        model_error = np.mean(
            np.minimum(np.abs(z - reconstruction), 4.0 * scale)
        )
        local_error = np.mean(
            np.minimum(np.abs(z - local), 4.0 * scale)
        )
        if model_error > 1.03 * local_error:
            continue
        if _turns(reconstruction).size > _turns(local).size:
            continue

        candidates.append(reconstruction)

    return candidates


def _candidate_bank(z, window_size):
    """Build multiscale smoothers and numerically stable AR modal candidates."""
    robust = _median3(z)
    n = z.size
    candidates = []
    for mult in (1.0, 1.7, 2.6, 3.8):
        candidates.append(_smooth(robust, max(5, int(mult * window_size) | 1)))

    # A low-order, zero-phase lowpass supplies a different smoothness shape.
    if _HAVE_SCIPY and n >= 18:
        for cutoff in (0.055, 0.09):
            try:
                sos = butter(3, cutoff, btype="lowpass", output="sos")
                candidates.append(np.asarray(sosfiltfilt(sos, robust), dtype=float))
            except Exception:
                pass

    if n >= 32 and candidates:
        candidates.extend(_ar_modal_candidates(robust, candidates[0]))
    return robust, candidates


def _tail_score(y, z, start, scale, window_size):
    yt = y[start:]
    zt = z[start:]
    if yt.size < 3 or not np.all(np.isfinite(yt)):
        return np.inf
    turns = _turns(yt)
    fidelity = np.mean(np.abs(yt - zt)) / scale
    qstart = max(0, yt.size - max(window_size, yt.size // 4))
    recent = np.mean(np.abs(yt[qstart:] - zt[qstart:])) / scale

    # Reward sparse turning topology, while retaining bounded observation fit.
    return (0.42 * min(turns.size / 50.0, 2.0) +
            0.33 * min(fidelity, 2.0) +
            0.25 * min(recent, 2.0))


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1 or x.size < window_size:
        raise ValueError("Input signal length must be >= window_size")

    z = _finite_signal(x)
    if z.size <= 3:
        return z[window_size - 1:].copy()

    robust, raw_candidates = _candidate_bank(z, window_size)
    start = window_size - 1
    noise = max(_sigma(np.diff(z)), np.finfo(float).eps)
    best = None
    best_score = np.inf

    for base in raw_candidates:
        if base.size != z.size or not np.all(np.isfinite(base)):
            continue
        residual_scale = _sigma(z - base)
        projected = _persistence_project(base, residual_scale, window_size)

        # Controlled residual injection improves noisy-observation fidelity
        # without admitting unbounded single-sample excursions.
        limit = 1.25 * max(residual_scale, noise * 0.25)
        residual = np.clip(robust - projected, -limit, limit)
        for alpha in (0.0, 0.06, 0.13, 0.22):
            trial = projected + alpha * residual
            trial = _persistence_project(
                trial, residual_scale * (1.0 + 0.35 * alpha), window_size
            )
            score = _tail_score(trial, z, start, noise, window_size)
            if score < best_score:
                best_score = score
                best = trial

    if best is None or not np.all(np.isfinite(best)):
        best = _smooth(z, max(5, 2 * window_size + 1))
    return np.asarray(best[start:], dtype=float).copy()


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    return clean_signal + rng.normal(0, noise_level, length), clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    if clean_signal is None:
        return {
            "filtered_signal": filtered,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered),
        }

    delay = window_size - 1
    clean = clean_signal[delay:delay + len(filtered)]
    noisy = noisy_signal[delay:delay + len(filtered)]
    m = min(filtered.size, clean.size, noisy.size)
    filtered, clean, noisy = filtered[:m], clean[:m], noisy[:m]

    if m > 1 and np.std(filtered) > 0 and np.std(clean) > 0:
        corr = float(np.corrcoef(filtered, clean)[0, 1])
    else:
        corr = 0.0
    before = float(np.var(noisy - clean))
    after = float(np.var(filtered - clean))
    reduction = (before - after) / before if before > 0 else 0.0

    return {
        "filtered_signal": filtered,
        "clean_signal": clean,
        "noisy_signal": noisy,
        "correlation": corr,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    result = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {result['correlation']:.3f}")
    print(f"Noise reduction: {result['noise_reduction']:.3f}")
    print(f"Processed signal length: {result['signal_length']}")

